import{_ as i,o as t,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Checklist thực hiện — IMPLEMENTING","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-crawler-management/task.md","filePath":"feature/admin-crawler-management/task.md"}'),a={name:"feature/admin-crawler-management/task.md"};function o(l,e,c,s,h,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="checklist-thuc-hien-—-implementing" tabindex="-1">Checklist thực hiện — IMPLEMENTING <a class="header-anchor" href="#checklist-thuc-hien-—-implementing" aria-label="Permalink to &quot;Checklist thực hiện — IMPLEMENTING&quot;">​</a></h1><ul><li>[x] Review 18 BA còn lại (giữ mã cũ, bỏ BA-01 và BA-17) và chốt 6 quyết định trong spec.</li><li>[x] Đọc đủ spec/plan/task/test, kiểm tra AGENTS/CLAUDE/rule của repo trước code.</li><li>[x] Chuẩn hóa Docker deps/browser và kiểm chứng non-root, không bake session/env vào image.</li><li>[x] Thiết kế persistent runtime root, migration và rollback config/session/manifest/history.</li><li>[x] Xác định scheduler owner, khóa chạy chung, heartbeat và timezone migration.</li><li>[x] API readiness nhiều check độc lập, phân biệt stale/unknown và manual/scheduled.</li><li>[x] API session upload/metadata/probe/revoke, version và bản làm việc theo run.</li><li>[ ] Secret encryption, TLS nội bộ, limits, allowlist và redaction; không thêm account/role.</li><li>[x] Proxy/TikTok masked replace/probe; kiểm soát rate/cost và no-direct-fallback.</li><li>[x] Nguồn/giới hạn và preview snapshot, chọn platform cho một run.</li><li>[x] Stop-request state machine, flush/manifest closure và xử lý batch đã gửi.</li><li>[x] Event/log/detail/history pagination và recovery; dùng <code>/admin?view=trends</code> hiện có để kiểm tra dữ liệu đầu ra.</li><li>[ ] Business auth/audit/file validation/error contracts; kiểm tra secret logging gateway.</li><li>[x] Web layout các mục, form trạng thái và run details trên trang hiện có.</li><li>[x] Cập nhật key song song <code>vi/admin.json</code> + <code>en/admin.json</code>, không hardcode UI text.</li><li>[ ] Kiểm tra light/dark mode, keyboard/screen reader và responsive.</li><li>[ ] Chạy tests bảo mật, concurrency, restart, publication và stop/recovery theo test.md.</li><li>[x] Chạy Web <code>npm run ci</code>, AI checks và Business checks phù hợp theo CI repo.</li><li>[ ] Review diff + demo dev + xác nhận readiness triển khai; không tự thay production.</li><li>[ ] Sau khi được phép: CI/CD deploy immutable image/migration có backup và smoke checks.</li><li>[ ] P1 BA-16/20 chỉ thực hiện khi scope này được duyệt.</li></ul><h2 id="ket-qua-dev" tabindex="-1">Kết quả dev <a class="header-anchor" href="#ket-qua-dev" aria-label="Permalink to &quot;Kết quả dev&quot;">​</a></h2><ul><li><p>Đã hiện thực nhóm P0 ở code và P1 cảnh báo/retry nguồn Facebook như giới hạn ghi trong plan.</p></li><li><p>Secret encryption/allowlist/redaction và chặn Business → AI qua HTTP ngoài loopback đã có code/test. TLS thực tế toàn đường truyền, key mount và migration production là release gates chưa thực hiện.</p></li><li><p>Đã kiểm tra UI vi/en, light/dark, mobile 390px không tràn ngang, keyboard Escape và semantic accessibility tree. Chưa kiểm bằng thiết bị screen reader thực tế.</p></li><li><p>Regression: 23 Python tests, 9 Java tests; Web npm run ci đạt. Docker image build đạt; browser offline non-root đạt; container recreation giữ credential/config/history bằng volume giả đạt.</p></li><li><p>Chưa chạy crawl thật, chưa thử provider/proxy thật, chưa E2E worker với dịch vụ production và chưa deploy. Các task kiểm chứng toàn hệ thống/release vẫn mở để không ghi nhận hoàn tất giả.</p></li><li><p>[x] Sửa browser readiness theo Python của runner, thêm mã lỗi rõ ràng cho local/Windows và kiểm tra venv thực tế. API local đã trả Browser OK và manualReady true.</p></li></ul><h2 id="proxy-runtime-docker" tabindex="-1">Proxy runtime Docker <a class="header-anchor" href="#proxy-runtime-docker" aria-label="Permalink to &quot;Proxy runtime Docker&quot;">​</a></h2><ul><li>[x] Thay luồng ghi dotenv bằng resolver trong bộ nhớ và truyền env cho child.</li><li>[x] Retry Facebook và Threads dùng resolver chung; lỗi proxy dừng sớm và giữ manifest/delivery.</li><li>[x] Kiểm tra regression thiếu .env, env cũ, provider/TCP lỗi, fixed/direct và log không lộ secret.</li></ul><h2 id="session-ram-theo-yeu-cau-2026-11-02" tabindex="-1">Session RAM theo yêu cầu (2026-11-02) <a class="header-anchor" href="#session-ram-theo-yeu-cau-2026-11-02" aria-label="Permalink to &quot;Session RAM theo yêu cầu (2026-11-02)&quot;">​</a></h2><ul><li>[x] Store RAM và IPC stdin cho preflight/run/probe/CLI; bỏ fallback file/Redis trong luồng admin session.</li><li>[x] UI upload session không cần khóa, thông báo mất session khi restart; giữ bảo vệ proxy/TikTok.</li><li>[x] Test snapshot/revoke/restart/no-write/child handoff, validation và Web CI.</li></ul>',8)])])}const g=i(a,[["render",o]]);export{m as __pageData,g as default};
